exploreUrl:
@js:var awa = `{{source.key}}/discover.php`;
var response = java.ajax(awa);
var json = JSON.parse(response);
var categories = json.data || [];
var menu = [];

for (var i = 0; i < categories.length; i++) {
    var cat = categories[i];
    // 根据标题内容判断是否为标题
    var isHeader = (cat.title.indexOf("☆") !== -1) ||
                   (cat.title.indexOf("❀") !== -1) ||
                   (cat.title.indexOf("°・") !== -1) ||
                   (cat.title.indexOf("🔖") !== -1) ||
                   (cat.title.endsWith("❀❀❀"));
    if (isHeader) {
        menu.push({
            title: cat.title,
            url: "",
            style: {
                layout_flexGrow: 1,
                layout_flexBasisPercent: 1.0,
                textAlign: "center",
                fontWeight: "bold"
            }
        });
    } else {
        var listUrl = awa + "?source=" + encodeURIComponent(cat.source)
                    + "&path=" + encodeURIComponent(cat.path)
                    + "&page={{page}}";
        menu.push({
            title: cat.title,
            url: listUrl,
            style: { layout_flexGrow: 1, layout_flexBasisPercent: 0.35 }
        });
    }
}
JSON.stringify(menu);

ruleContent.content:
@js:(function() {
    var data;
    try {
        data = typeof result === 'string' ? JSON.parse(result) : result;
    } catch(e) {
        java.log("解析JSON失败: " + e);
        return "";
    }

    // 1. 检测是否为音频类型（听书/音乐）
    if (data.type === 'audio' || data.type === 'music') {
        var audioUrl = data.data && (data.data.audio_url || data.data.music_url);
        if (audioUrl) {
            return audioUrl;
        } else {
            java.log("音频类型但未找到音频链接");
            return "";
        }
    }

    // 2. 原有逻辑：content 或 images
    if (data.content) {
        return data.content;
    }

    if (data.images && Array.isArray(data.images) && data.images.length) {
        return data.images.map(function(img) {
            var url = typeof img === 'string' ? img : img.url || img.src;
            return '<img src="' + url + '">';
        }).join('\n');
    }

    java.log("未找到content、images或音频链接");
    return "";
})();

ruleSearch.bookList:
@js:(function() {
    var data;
    try {
        data = typeof src === 'string' ? JSON.parse(src) : src;
    } catch(e) {
        return [];
    }

    if (!data || !data.results || typeof data.results !== 'object') {
        return [];
    }

    var resultList = [];
    var results = data.results;
    var keys = Object.keys(results);
    for (var k = 0; k < keys.length; k++) {
        var key = keys[k];
        var source = results[key];
        if (!source.data || !Array.isArray(source.data)) {
            continue;
        }
        var sourceName = source.name || key;
        var items = source.data;
        for (var i = 0; i < items.length; i++) {
            var item = items[i];
            var newItem = {};
            // 复制原对象所有自有属性
            for (var prop in item) {
                if (item.hasOwnProperty(prop)) {
                    newItem[prop] = item[prop];
                }
            }
            newItem.sourceName = sourceName;
            newItem.url = "detail.php?source=" + key + "&book_id=" + item.book_id;
            resultList.push(newItem);
        }
    }
    return resultList;
})();
